// src/hooks/useBookManagement.js

import { useState } from 'react';
import axios from 'axios'; 

const API_BASE_URL = 'http://localhost:5000/api/books'; 

export const useBookManagement = () => {
    const [isLoading, setIsLoading] = useState(false);
    const [error, setError] = useState(null);
    const [successMessage, setSuccessMessage] = useState(null);

    const registerBook = async (bookFormData) => {
        setIsLoading(true);
        setError(null);
        setSuccessMessage(null);
        
        try {
            // Llama al endpoint POST /api/books/register
            const response = await axios.post(`${API_BASE_URL}/register`, bookFormData, {
                // Axios maneja el 'Content-Type: multipart/form-data' automáticamente.
            });

            setSuccessMessage(response.data.message || "Libro registrado exitosamente.");
            setIsLoading(false);
            
            return { success: true };

        } catch (err) {
            setIsLoading(false);
            
            const backendMessage = err.response?.data?.message || "Error de conexión o error desconocido.";
            setError(backendMessage);
            
            return { success: false, error: backendMessage };
        }
    };

    return {
        registerBook,
        isLoading,
        error,
        successMessage,
        setError, 
        setSuccessMessage 
    };
};
